import numpy as np
from scipy.spatial.transform import Rotation as R
from scipy.optimize import least_squares
origins=[([0,0,.333],[0,0,0]),([0,0,0],[-np.pi/2,0,0]),([0,-.316,0],[np.pi/2,0,0]),([.0825,0,0],[np.pi/2,0,0]),([-.0825,.384,0],[-np.pi/2,0,0]),([0,0,0],[np.pi/2,0,0]),([.088,0,0],[np.pi/2,0,0])]
def tf(p,r):
 t=np.eye(4);t[:3,:3]=R.from_euler('xyz',r).as_matrix();t[:3,3]=p;return t

def fk(q,extra=.0):
 t=tf([0,-.4,.78],[0,0,np.pi/2])
 for qi,(p,r) in zip(q,origins):t=t@tf(p,r)@tf([0,0,0],[0,0,qi])
 return t@tf([0,0,.107+extra],[0,0,-np.pi/4])
if __name__=='__main__':
 import json
 p=json.load(open('/app/output/initial/meta.json'))['proprio']['now'];q=p[:7]
 for e in [0,.1034]:
  t=fk(q,e);print(e,t[:3,3],R.from_matrix(t[:3,:3]).as_quat(scalar_first=True))
 print('observed',p[16:23])
PY
